import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"路线图","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/roadmap.md","filePath":"appendix/roadmap.md","lastUpdated":1794555917000}`),a={name:`appendix/roadmap.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="路线图" tabindex="-1">路线图 <a class="header-anchor" href="#路线图" aria-label="Permalink to “路线图”">​</a></h1><p>XiHan Framework 5 的路线图按门槛推进，不按日期。每个阶段列出退出条件，满足才进入下一阶段；没有「预计某月发布」这种承诺，因为我宁可晚一点，也不想为了赶日期把没通过门禁的东西放出去。这一页列出各阶段的内容、退出条件与当前状态。</p><h2 id="阶段总览" tabindex="-1">阶段总览 <a class="header-anchor" href="#阶段总览" aria-label="Permalink to “阶段总览”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>P0 定边界 → P1 内核 → P2 子系统 → P3 协议与宿主 → P4 插件与跨语言 → P5 GA → 后续版本</span></span></code></pre></div><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>退出条件</th><th>状态</th></tr></thead><tbody><tr><td>P0 定边界</td><td>总体方案拍板；目录骨架；规范草案（原语、清单、上下文、管道阶段、术语表）；CI 门禁</td><td>架构决策通过；原语层公开 API 进入冻结候选；空解决方案过全部门禁</td><td>完成</td></tr><tr><td>P1 内核</td><td>原语层；内核的清单解析、阶段化管道、调用上下文、生命周期状态机、诊断桥、安全原语；进程内插件；测试基座</td><td>零 Provider 的示例应用可运行；Native AOT 发布通过；内核预算达标</td><td>完成</td></tr><tr><td>P2 子系统</td><td>Domain 与持久化、缓存、消息、安全、多租户五个子系统的抽象、默认实现、一致性套件与首批 Provider；Minimal 与 Standard 组合包；本地化</td><td>Standard 组合应用在零外部设施下运行；换成 EF Core、Redis、RabbitMQ 只改配置与包引用；所有默认实现与 Provider 通过套件</td><td>完成</td></tr><tr><td>P3 协议与宿主</td><td>操作契约与源生成器；HTTP、gRPC、MCP、CloudEvents 适配器；命令行宿主；对象存储、调度、远程配置、审计；OpenTelemetry；<code>xihan pack</code>；Full 组合包</td><td>一份契约同时在三种协议上服务，共用一份 Schema；Kubernetes 示例通过探针与停机宽限对齐测试</td><td>完成</td></tr><tr><td>P4 插件与跨语言</td><td>进程外插件协议；Wasm 实验实现；Go SDK；规范独立仓库</td><td>Go 写的插件在 .NET 宿主中服务一个操作，崩溃时宿主降级不退出；Go SDK 通过全部一致性向量；规范仓库公开</td><td>完成</td></tr><tr><td>P5 GA</td><td>批量优先审查、SqlSugar Provider、能力补齐、工作流与 AI 子系统、BasicApp 接入、API 审查、包验证基线、性能基准、文档站</td><td>BasicApp 核心模块全量跑在框架上；全部门禁通过；性能目标达标</td><td>进行中</td></tr></tbody></table><h2 id="p5-的进度" tabindex="-1">P5 的进度 <a class="header-anchor" href="#p5-的进度" aria-label="Permalink to “P5 的进度”">​</a></h2><p>P5 的任务按执行顺序排列，前面的已经完成：</p><table tabindex="0"><thead><tr><th>任务</th><th>状态</th></tr></thead><tbody><tr><td>批量优先：抽象层所有对集合的操作都有一次调用完成的批量方法，逐项结果，Provider 原生批量；架构测试禁止在循环里调单条方法</td><td>完成</td></tr><tr><td><code>Persistence.SqlSugar</code>：依赖 <code>SqlSugarCore</code>，协议约定映射，SQLite 通过全部一致性用例</td><td>完成</td></tr><tr><td>能力补齐：租户分片、<code>IDistributedCache</code> 适配、S3 对象存储</td><td>完成</td></tr><tr><td><code>Messaging.Kafka</code>、<code>Caching.Hybrid</code>、<code>Configuration.Nacos</code></td><td>完成</td></tr><tr><td>调度子系统重做（引擎进抽象包，Provider 只实现存储与领导选举）与 <code>Scheduling.Database</code>、<code>Workflow.Database</code></td><td>完成</td></tr><tr><td>工作流与 AI 子系统：原计划放到后续版本，提前进入 5.0</td><td>完成</td></tr><tr><td>十项能力补齐：SqlSugar 多库与分表、Validate 阶段契约校验、领域事件派发、三个数据库 Provider、Resilience 阶段、Provider 健康项、OpenAPI 权限扩展</td><td>完成</td></tr><tr><td>雪花标识、OpenAPI 文案与分组、调用来源、条件引擎、IP 归属地、对象存储进阶能力、绕过管道的端点认证、运行信息、作业重试与执行时限、出站地址策略</td><td>完成</td></tr><tr><td>第一个与第二个预览版发布到 nuget.org</td><td>完成</td></tr><tr><td>BasicApp 接入：核心模块以能力包与操作契约重写在框架上</td><td>进行中</td></tr><tr><td>API 审查：所有公开 API 带稳定性标记，公开面从 <code>Unshipped</code> 转入 <code>Shipped</code></td><td>审查与修正完成；公开面在 5.0.0 的版本提交里转入 <code>Shipped</code></td></tr><tr><td>包验证基线、性能基准回归、安全审查、SBOM</td><td>进行中：每个包带 SBOM、CI 有性能门禁；包验证基线已接好，5.0.0 上架后启用；安全审查进行中</td></tr><tr><td>文档站：教程、逐包参考、规范链接</td><td>进行中，就是你正在读的这一站</td></tr><tr><td>发布 5.0.0，声明 LTS</td><td>待做</td></tr></tbody></table><h2 id="后续版本" tabindex="-1">后续版本 <a class="header-anchor" href="#后续版本" aria-label="Permalink to “后续版本”">​</a></h2><p>5.0 正式版之后的内容，按优先级：</p><table tabindex="0"><thead><tr><th>优先级</th><th>内容</th></tr></thead><tbody><tr><td>高</td><td><code>Search.*</code> 子系统（索引与查询的抽象、内存实现与 Elasticsearch 等 Provider）</td></tr><tr><td>高</td><td><code>Plugins.Wasm</code> 从 Experimental 到正式；TypeScript SDK</td></tr><tr><td>中</td><td>实时通信与网关的专门包（当前实时通信直接用 ASP.NET Core SignalR，见<a href="/web/realtime">实时通信</a>）</td></tr><tr><td>中</td><td><code>Actors.*</code> 子系统；Kubernetes Operator</td></tr><tr><td>中</td><td>管道阶段内的并行分支（计算图形态）</td></tr><tr><td>低</td><td><code>Persistence.MongoDB</code>、<code>Messaging.Nats</code>、<code>Scheduling.Quartz</code> 等更多 Provider</td></tr></tbody></table><p>有两件事在 5.0 里明确不做：把 4.x 的模块迁移到 5.0 的自动化工具，以及 4.x 到 5.0 的兼容层。4.x 单独维护，5.0 是一条新的线；自动迁移机制保留给 5.x 到 6.x。</p><h2 id="版本策略" tabindex="-1">版本策略 <a class="header-anchor" href="#版本策略" aria-label="Permalink to “版本策略”">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>规则</th></tr></thead><tbody><tr><td>版本线</td><td>所有包共享一条版本线，从 5.0.0 起；SemVer 2.0</td></tr><tr><td>大版本</td><td>每三年一次，对齐一个 .NET LTS；LTS 大版本三年活跃支持加一年安全修复</td></tr><tr><td>小版本</td><td>约每六个月；补丁随时</td></tr><tr><td>目标框架</td><td>当前 LTS；上一个 LTS 保留 12 个月过渡期</td></tr><tr><td>预览版</td><td><code>X.Y.Z-preview.N</code>，安装时带 <code>--prerelease</code></td></tr><tr><td>破坏性变更</td><td>大版本内为零；原语层永远为零，必须破坏时发布新包 ID 并存</td></tr></tbody></table><h2 id="性能目标" tabindex="-1">性能目标 <a class="header-anchor" href="#性能目标" aria-label="Permalink to “性能目标”">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>目标</th></tr></thead><tbody><tr><td>冷启动额外开销</td><td>在 ASP.NET Core 基线之上，JIT 下不超过 100 毫秒；Native AOT 下小于 50 毫秒</td></tr><tr><td>管道执行，单个中间件</td><td>小于 0.1 毫秒</td></tr><tr><td>管道执行，五个中间件</td><td>小于 0.5 毫秒</td></tr><tr><td>空应用常驻内存</td><td>框架额外不超过 15 MB（不含运行时自己的那一份）</td></tr><tr><td>原语层加内核的包大小</td><td>小于 500 KB</td></tr><tr><td>基准回归阈值</td><td>5%</td></tr></tbody></table><p>基准项目在仓库的 <code>framework/benchmarks</code> 下。CI 的「性能门禁」作业检查管道耗时与两个核心程序集的大小，并在同一台机器上与上一次提交比较，耗时、分配、冷启动或框架额外的常驻内存回退超过 5% 即阻断。JIT 下的冷启动与框架额外常驻内存超出上表即阻断（超线时复测一轮）；Native AOT 下的冷启动由按 AOT 发布的探针测，只报告。实测 Linux 上 JIT 冷启动约 80 毫秒、框架额外常驻内存约 13 MB，Windows 上 AOT 冷启动不到 1 毫秒。</p><h2 id="风险" tabindex="-1">风险 <a class="header-anchor" href="#风险" aria-label="Permalink to “风险”">​</a></h2><p>我把最大的几个风险也写在这里，免得读者只看到好的一面：</p><table tabindex="0"><thead><tr><th>风险</th><th>缓解</th></tr></thead><tbody><tr><td>抽象过度，只剩一堆接口</td><td>每个抽象必须有能用的默认实现；每个阶段的退出条件都是「跑起来」</td></tr><tr><td>规范成为没人实现的文档</td><td>第二语言 SDK 是 P4 的退出条件，不是愿景；现在已经有了</td></tr><tr><td>单人维护带宽不足</td><td>当前范围只含内核与 Standard、Full 两组子系统，其余进孵化区</td></tr><tr><td>源生成器与 AOT 成本</td><td>允许手写替代；生成器只覆盖操作登记、契约 Schema 与仓储登记</td></tr><tr><td>命名漂移</td><td>术语表走规范流程，包 ID 文法由架构测试强制</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/appendix/milestones">发展大事记</a>：各阶段实际发生的事</li><li><a href="/changelog">更新日志</a>：每个版本的变更</li><li><a href="/appendix/contributing">贡献指南</a>：想参与某个后续版本的任务，从这里开始</li></ul>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};